SELECT p.post_id AS postId, p.board_id AS boardId, b.name AS boardName, p.title, p.view_count AS viewCount, p.created_at AS created, (SELECT COUNT(*) FROM post_likes pl WHERE pl.post_id = p.post_id) AS likeCount FROM posts p INNER JOIN boards b ON p.board_id = b.board_id WHERE p.user_id = #{userId} AND p.state = 'normal' AND p.board_id = #{boardId}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY
p.view_count DESC, p.post_id DESC p.created_at DESC, p.post_id DESC
LIMIT #{size} OFFSET #{offset}

SELECT cm.comment_id AS commentId, cm.content, cm.created_at AS created, p.post_id AS postId, p.board_id AS boardId, p.title AS postTitle FROM comments cm INNER JOIN posts p ON cm.post_id = p.post_id WHERE cm.user_id = #{userId} AND cm.state = 'normal' AND p.state = 'normal' AND p.board_id = #{boardId}
AND (cm.content LIKE CONCAT('%', #{keyword}, '%') OR p.title LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY cm.created_at DESC, cm.comment_id DESC LIMIT #{size} OFFSET #{offset}

SELECT p.post_id AS postId, p.board_id AS boardId, b.name AS boardName, p.title, p.view_count AS viewCount, p.created_at AS created, (SELECT COUNT(*) FROM post_likes l WHERE l.post_id = p.post_id) AS likeCount FROM post_likes pl INNER JOIN posts p ON pl.post_id = p.post_id INNER JOIN boards b ON p.board_id = b.board_id WHERE pl.user_id = #{userId} AND p.state = 'normal' AND p.board_id = #{boardId}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY
p.view_count DESC, p.post_id DESC pl.created_at DESC, p.post_id DESC
LIMIT #{size} OFFSET #{offset}
